\documentclass{article}
% A0 portrait: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{booktabs}
\usepackage{array}
\pagestyle{empty}

% ── Samsung Galaxy Color Theme ──
\definecolor{primary}{HTML}{0A1228}      % deep navy (title bar)
\definecolor{secondary}{HTML}{3C82F6}    % samsung blue
\definecolor{accent}{HTML}{D4AF37}       % gold/copper for premium
\definecolor{bgposter}{HTML}{060A14}     % near-black background
\definecolor{cardbg}{HTML}{0F1420}       % card background
\definecolor{cardbg2}{HTML}{12182A}      % alternate card
\definecolor{cardbg3}{HTML}{0D1120}      % dark card
\definecolor{cardtitlebg}{HTML}{1A2040}  % card title bar
\definecolor{textlight}{HTML}{E8ECF2}    % light text
\definecolor{textgray}{HTML}{94A3B8}     % gray text
\definecolor{stathighlight}{HTML}{1A2A50}% stat box bg
\definecolor{newbadge}{HTML}{D4AF37}     % NEW badge gold
\definecolor{aiaccent}{HTML}{60A5FA}     % light blue for AI

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{secondary},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.22},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg2,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.22},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg3,
    borderline west={6pt}{0pt}{aiaccent},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{aiaccent},
    coltitle=aiaccent, colbacktitle=cardtitlebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={aiaccent!50},
    valign=top, drop shadow={opacity=0.22},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!25!white,
    borderline west={8pt}{0pt}{accent},
    left=18pt, right=16pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.25},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════
% TITLE BAR (span=3)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=50pt, right=50pt, top=20pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{90}{108}\selectfont\bfseries Samsung Galaxy Ecosystem 2025}\\[16pt]
  {\fontsize{42}{52}\selectfont\color{accent} Innovation Across Every Category}\\[12pt]
  {\fontsize{32}{40}\selectfont\color{textgray} Discover the complete Galaxy lineup --- smartphones, foldables, wearables, audio, and smart home, all powered by AI.}
}

% ═══════════════════════════════════════════════════════
% STATS BANNER (span=3)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!20!bgposter, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center, borderline south={4pt}{0pt}{secondary!40},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{secondary} 7+}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textlight} Product Categories}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{accent} 2}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textlight} New 2025 Launches}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{secondary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{secondary} 14}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textlight} Featured Products}\vspace{10pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \fcolorbox{aiaccent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{aiaccent} 4+}\\[6pt]
      {\fontsize{28}{34}\selectfont\color{textlight} AI-Branded Products}\vspace{10pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════
% ROW A: Hero Launches (row6 to row11)
% ═══════════════════════════════════════════════════════

% ── S26 Ultra (col 1) ──
\posterbox[goldcard, title={\colorbox{newbadge}{\color{black}\textbf{NEW}}\hspace{8pt}Galaxy S26 Ultra}
]{name=s26, column=1, between=row6 and row11}{
  \vspace{4pt}
  \posterfig{0.92}{figures/s26_ultra.png}{Samsung's most advanced smartphone for 2025}
  \vspace{4pt}
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Pro-grade 200MP camera system
    \item Integrated S Pen functionality
    \item Premium materials and build
    \item Galaxy AI on-device intelligence
  \end{itemize}
}

% ── Buds4 Pro (col 2) ──
\posterbox[goldcard, title={\colorbox{newbadge}{\color{black}\textbf{NEW}}\hspace{8pt}Galaxy Buds4 Pro}
]{name=buds, column=2, between=row6 and row11}{
  \vspace{4pt}
  \posterfig{0.92}{figures/buds4_pro.png}{Next-generation ANC and hi-fi audio}
  \vspace{4pt}
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Next-gen active noise cancellation
    \item High-fidelity audio playback
    \item Seamless pairing with all Galaxy devices
    \item Galaxy AI-enhanced sound
  \end{itemize}
}

% ── AI Integration (col 3) ──
\posterbox[darkcard, title={AI-Powered Everything}
]{name=ai, column=3, between=row6 and row11}{
  \vspace{6pt}
  \centering
  \includegraphics[width=0.65\linewidth]{figures/ai_brain.png}\\[8pt]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{AI is the foundation of the entire 2025 lineup}}\vspace{6pt}
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Bespoke AI} --- refrigerators, laundry, climate
    \item \textbf{Galaxy AI} --- photography, productivity, translation
    \item Smart energy management and automation
    \item Personalized usage pattern learning
  \end{itemize}
}

% ═══════════════════════════════════════════════════════
% ROW B: Ecosystem + Category Table (row11 to row17)
% ═══════════════════════════════════════════════════════

% ── Ecosystem Diagram (col 1-2, span=2) ──
\posterbox[bluecard, title={The Complete Galaxy Ecosystem}
]{name=ecosystem, column=1, span=2, between=row11 and row17}{
  \vspace{4pt}
  \posterfig{0.96}{figures/ecosystem.png}{8 product categories connected by Galaxy AI}
  \vspace{6pt}
  \fontsize{30}{40}\selectfont
  \centering
  \colorbox{secondary!18}{\parbox{0.94\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{32}{40}\selectfont\color{textlight}\textbf{From pocket to living room --- every device works better together}}\vspace{8pt}%
  }}
}

% ── Why It Matters (col 3) ──
\posterbox[bluecard, title={Why It Matters}
]{name=why, column=3, between=row11 and row14}{
  \fontsize{32}{42}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item Seamless, AI-enhanced experience across all categories
    \item Every device works better together
    \item Compelling reason to buy into the full Samsung experience
    \item One ecosystem from pocket to kitchen to living room
  \end{itemize}
}

% ── Key Message (col 3) ──
\posterbox[highlightcard, title={The Galaxy Advantage}
]{name=advantage, column=3, between=row14 and row17}{
  \fontsize{34}{44}\selectfont
  \centering
  \vspace{10pt}
  {\color{accent}\textbf{14 products.}}\\[8pt]
  {\color{secondary}\textbf{7+ categories.}}\\[8pt]
  {\color{white}\textbf{One unified AI ecosystem.}}\\[12pt]
  {\fontsize{30}{38}\selectfont\color{textgray} Samsung's most comprehensive consumer technology portfolio.}
}

% ═══════════════════════════════════════════════════════
% ROW C: Category Highlights Table (row17 to bottom)
% ═══════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=12pt, bottom=12pt,
  borderline north={4pt}{0pt}{secondary!50},
]{name=tablebox, column=1, span=3, between=row17 and bottom}{
  \centering
  {\fontsize{42}{50}\selectfont\bfseries\color{secondary} Category Highlights at a Glance}\\[14pt]
  \renewcommand{\arraystretch}{1.8}
  \fontsize{26}{34}\selectfont
  \begin{tabular}{>{\bfseries\color{secondary}}l >{\color{textlight}}l >{\color{accent}\bfseries}c}
    \toprule
    \rowcolor{cardtitlebg}
    \color{white}\textbf{Category} & \color{white}\textbf{Product} & \color{white}\textbf{Status} \\
    \midrule
    Smartphones & Galaxy S26 Ultra & NEW \\
    \rowcolor{cardbg2}
    Foldables & Galaxy Z Fold7 & Current \\
    Foldables & Galaxy Z Flip7 & Current \\
    \rowcolor{cardbg2}
    Tablets & Galaxy Tab S11 Series & Current \\
    Wearables & Galaxy Watch Ultra & Current \\
    \rowcolor{cardbg2}
    Audio & Galaxy Buds4 Pro & NEW \\
    Television & Neo QLED 8K TV & Current \\
    \rowcolor{cardbg2}
    Television & The Frame Pro & Current \\
    Audio / Home & Q-series Soundbar & Current \\
    \rowcolor{cardbg2}
    Monitors & Odyssey OLED G9 & Current \\
    Kitchen & Bespoke AI Refrigerator & Current \\
    \rowcolor{cardbg2}
    Laundry & Bespoke AI Laundry & Current \\
    Cleaning & Jet Stick Vacuums & Current \\
    \rowcolor{cardbg2}
    Climate & Air Conditioners & Current \\
    \bottomrule
  \end{tabular}
}

\end{tcbposter}
\end{document}
